 ev=read(U/'EVALUATION.json');emp=read(U/'EMPIRICAL_RANGE.json');control=read(U/'CONTROLS.json');gate=read(U/'FINAL_GATE.json');rs=rows();rd={r['alias']:r for r in rs};examples=[]
 for item in emp['development']:
  r=rd[item['alias']];a=arrays(r);auto=dict(np.load(U/'runs/42/auto'/f"{r['alias']}.npz"));refs=[]
  for pair in item['pairs']:
   ref=rd[pair['reference']];ra=arrays(ref)
   refs.append(dict(alias=ref['alias'],person=ref['person'],source=Path(ref['source']).as_uri(),pair=pair,seconds=(ra['timestamp_us']/1e6).tolist(),y=[float(v) if ok else None for v,ok in zip(ra['x'][:,29],support(ra))]))
  examples.append(dict(alias=r['alias'],label=r['label'],source=Path(r['source']).as_uri(),frames=a['frame_id'].tolist(),seconds=(a['timestamp_us']/1e6).tolist(),y=[float(v) if ok else None for v,ok in zip(a['x'][:,29],support(a))],new=auto['pred'].tolist(),old=auto['old'].tolist(),geometry=auto['geometry'].tolist(),cores=[e for e in ev['events'] if e['alias']==r['alias']],refs=refs,proximity=item['observed_proximity'],evidence=item['evidence_status'],threshold=item['threshold'],nearest=item['nearest_distance'],episodes=runs(auto['pred'],a['frame_id'],a['timestamp_us'])))
 web=read(U/'WEB_RESULT.json') if (U/'WEB_RESULT.json').exists() else None
 payload=dict(examples=examples,window=[r for r in ev['known_windows'] if r['role']=='development'],automatic=ev['automatic_core'],control=dict(total=control['total'],passed=control['passed']),gate=gate,web=web)
